// === Tab: mySketch ===
// 整えるの面倒だったから雑に詰め合わせた
// reference:http://paulbourke.net/fractals/peterdejong/

x=y=100;
typeId = 0;
const ID_MAX = 8;
setup=_=>{
  createCanvas(600,600);
  colorMode(HSB,100);
  noStroke();
  background(0);
}
draw=_=>{
  translate(300,300);
  r=400;while(r--){
		dejong();
  }
}

function dejong(){
	window["dejong" + typeId]();
}

function dejong0(){
  u=x;v=y;
  a = -0.709; b = 1.638; c = 0.452; d = 1.740;
  x=f7(a*v) - f8(b*u);y=f7(c*u)-f8(d*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x * 100 + 10, y * 110 + 30, 2);
}

function dejong1(){
  u=x;v=y;
  a = 2.01; b = -2.53; c = 1.61; d = -0.33;
  x=f7(a*v) - f8(b*u);y=f7(c*u)-f8(d*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x*100, y*140 + 140, 2);
}

function dejong2(){
  u=x;v=y;
  a = -2; b = -2; c = -1.2; d = 2; // なかなか良い
  x=f7(a*v) - f8(b*u);y=f7(c*u)-f8(d*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(20 + x*100, 30 + y*110, 2);
}

function dejong3(){
  u=x;v=y;
  a = -2.3; b = -1.7; c = -1.2; d = 2;
  x=f3(a*v) - f4(b*u);y=f3(c*u)-f4(d*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x*125, 60+y*180, 2);
}

function dejong4(){
  u=x;v=y;
  a = 1.5; b = 2.7; c = 0.8; d= 1.7;
  x=f3(a*v) - f4(b*u);y=f3(c*u)-f4(d*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x*125, 60+y*180, 2);
}

function dejong5(){
  u=x;v=y; // ドーナツ
  a = 1.40; b = 1.56; c = 1.40; d = -6.56;
  x=d*f1(a*u)-f1(b*v);y=c*f2(a*u)+f2(b*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x * 32, y * 64, 2);
}

function dejong6(){
  u=x;v=y;
  a = 1.30; b = 1.56; c = 1.60; d = -4.56;
  x=d*f7(a*u)-f7(b*v);y=c*f8(a*u)+f8(b*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x * 40, y * 80 - 80, 2);
}

function dejong7(){
  u=x;v=y;
  a = 3; b = -1.9; c = 1.4;d = -1.5;
  x=d*f7(a*u)-f7(b*v);y=c*f8(a*u)+f8(b*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x * 80, y * 80 - 80, 2);
}

function dejong8(){
  u=x;v=y;
  a=-2.4;b=-0.2;c=-1.86;d=-3.5;
  x=d*f7(a*u)-f7(b*v);y=c*f8(a*u)+f8(b*v);
  fill(25+x*5+y*5,60+x*6-y*6,100,30);
  circle(x*50,y*80-60,2);
}

function mouseClicked(){
	background(0);
	typeId++;
	if(typeId > ID_MAX){ typeId = 0; }
	x=y=100;
}

// utility.
function f1(x){ return sin(x); }
function f2(x){ return cos(x); }
function f3(x){
  let m = floor(abs(x) * 0.5 / PI) + 2;
  x += 2 * PI * m;
  x = x % TAU;
  return max(min((2 / PI) * x, 2 - (2 / PI) * x), (2 / PI) * (x - 2 * PI));
}
function f4(x){ return f3(x + PI / 2); }
function f5(x){ return f1(x) + f3(x); }
function f6(x){ return f2(x) + f4(x); }
function f7(x){ return f1(x) + 0.5 * f1(2 * x) + 0.25 * f1(4 * x); }
function f8(x){ return f2(x) + 0.5 * f2(2 * x) + 0.25 * f2(4 * x); }

